css:
*{box-sizing:border-box}
.wrap{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:var(--hatch-widget-text,#26303b);max-width:760px;margin:0 auto}
.stage{position:relative;width:100%;aspect-ratio:900/520;border-radius:22px;overflow:hidden;border:1px solid var(--hatch-widget-border,#d8e2e8);background:linear-gradient(180deg,#7ec8f2 0%,#dff6ff 55%,#cdeec9 55.2%,#a5d189 78%,#7fb95f 100%)}
.pond{position:absolute;right:4%;bottom:3%;width:42%;height:19%;background:#7fd1e8;border-radius:50%;box-shadow:inset 0 6px 0 rgba(255,255,255,.35)}
.obj{position:absolute;cursor:grab;touch-action:none;user-select:none}
.obj svg{display:block;width:100%;height:auto;overflow:visible}
.obj .tag{position:absolute;left:50%;top:-24px;transform:translateX(-50%);background:#53382a;color:#fff;font-size:11.5px;padding:2.5px 9px;border-radius:999px;white-space:nowrap;opacity:0;transition:opacity .25s;pointer-events:none}
.obj:hover .tag,.obj.sel .tag{opacity:1}
.obj.sel{outline:2.5px dashed #e8873a;outline-offset:5px;border-radius:10px}
.obj.off svg *{animation-play-state:paused!important}
.obj.off{animation-play-state:paused}
.obj.flipped svg{transform:scaleX(-1)}
.obj.hiddenObj{opacity:.14}
.drift{animation:objDrift var(--dur,20s) ease-in-out infinite alternate}
@keyframes objDrift{from{transform:translate(0,0)}to{transform:translate(var(--dx,40px),var(--dy,0px))}}
.flyObj{animation:flyObj 24s linear infinite}
@keyframes flyObj{from{transform:translateX(-150px)}to{transform:translateX(940px)}}

.ol{stroke:#53382a;stroke-width:3;stroke-linejoin:round;stroke-linecap:round}
.sway{transform-box:fill-box;transform-origin:50% 100%;animation:sway 5.2s ease-in-out infinite}
@keyframes sway{0%,100%{transform:rotate(-1.3deg)}50%{transform:rotate(1.5deg)}}
.leg{transform-box:fill-box;transform-origin:50% 0%;animation:step .62s ease-in-out infinite alternate}
.leg.b{animation-delay:-.31s}
@keyframes step{from{transform:rotate(11deg)}to{transform:rotate(-11deg)}}
.graze{transform-box:fill-box;transform-origin:15% 85%;animation:graze 8s ease-in-out infinite}
@keyframes graze{0%,55%,100%{transform:rotate(0deg)}72%,86%{transform:rotate(24deg)}}
.hop{animation:hop 1.7s ease-in-out infinite}
@keyframes hop{0%,100%{transform:translateY(0) scale(1,1)}32%{transform:translateY(-14px) scale(.97,1.03)}56%{transform:translateY(0) scale(1.06,.93)}72%{transform:translateY(0) scale(1,1)}}
.ear{transform-box:fill-box;transform-origin:50% 100%;animation:earA 1.7s ease-in-out infinite}
@keyframes earA{0%,100%{transform:rotate(0deg)}38%{transform:rotate(-9deg)}60%{transform:rotate(5deg)}}
.wag{transform-box:fill-box;transform-origin:0% 90%;animation:wagA 1.9s ease-in-out infinite}
.flick{transform-box:fill-box;transform-origin:20% 95%;animation:wagA 2.6s ease-in-out infinite}
@keyframes wagA{0%,100%{transform:rotate(-7deg)}50%{transform:rotate(13deg)}}
.blinkE{transform-box:fill-box;transform-origin:center;animation:blinkA 4.4s infinite}
@keyframes blinkA{0%,92%,100%{transform:scaleY(1)}95%{transform:scaleY(.1)}}
.tilt{transform-box:fill-box;transform-origin:center;animation:tiltA 7s ease-in-out infinite}
@keyframes tiltA{0%,60%,100%{transform:rotate(0deg)}74%,88%{transform:rotate(-10deg)}}
.paddle{transform-box:fill-box;transform-origin:center;animation:paddleA 1.1s ease-in-out infinite alternate}
@keyframes paddleA{from{transform:rotate(-16deg)}to{transform:rotate(18deg)}}
.bobA{animation:bobAn 3s ease-in-out infinite}
@keyframes bobAn{0%,100%{transform:translateY(0) rotate(-1.6deg)}50%{transform:translateY(-3px) rotate(1.8deg)}}
.jumpF{animation:jumpA 5.2s ease-in-out infinite;opacity:0}
@keyframes jumpA{0%,58%,100%{transform:translate(0,10px);opacity:0}66%{opacity:1}78%{transform:translate(24px,-38px) rotate(-24deg);opacity:1}90%{transform:translate(46px,8px) rotate(22deg);opacity:1}96%{opacity:0}}
.throat{transform-box:fill-box;transform-origin:center;animation:throatA 1.3s ease-in-out infinite}
@keyframes throatA{0%,100%{transform:scale(.75)}50%{transform:scale(1.2)}}
.flapW{transform-box:fill-box;transform-origin:center;animation:flapA .48s ease-in-out infinite alternate}
@keyframes flapA{from{transform:scaleY(.35)}to{transform:scaleY(1)}}
.bwing{transform-box:fill-box;transform-origin:center;animation:bwingA .3s ease-in-out infinite alternate}
@keyframes bwingA{from{transform:scaleX(.35)}to{transform:scaleX(1)}}
.petal{animation:petalA linear infinite;opacity:0}
@keyframes petalA{0%{transform:translate(0,-6px) rotate(0deg);opacity:0}12%{opacity:.95}100%{transform:translate(-8px,120px) rotate(280deg);opacity:0}}

.status{margin-top:12px;background:var(--hatch-widget-surface,#fff);border:1px solid var(--hatch-widget-border,#ddd);border-radius:12px;padding:11px 14px;line-height:1.55}
.panel{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}
.panel button,.controls button{border:1px solid var(--hatch-widget-border,#ccc);background:var(--hatch-widget-surface,#fff);color:var(--hatch-widget-text,#222);border-radius:999px;padding:7px 12px;cursor:pointer;font-size:13.5px}
.panel button.on,.controls button.on{background:var(--hatch-widget-accent,#2f7f86);color:var(--hatch-widget-on-accent,#fff);border-color:transparent}
.controls{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}
.note{color:var(--hatch-widget-muted,#666);font-size:13px;margin-top:8px;line-height:1.55}
